#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K;
    if(!(cin >> n >> K)) return 0;
    int m = n - 1;
    vector<int> ea(m), eb(m);
    vector<int> start(n + 1, 0);
    for(int i = 0; i < m; ++i){
        int a, b; cin >> a >> b; --a; --b;
        ea[i] = a; eb[i] = b;
        start[a + 1]++; start[b + 1]++;
    }
    for(int i = 0; i < n; ++i) start[i + 1] += start[i];
    vector<int> adj(2 * (size_t)m);
    {
        vector<int> it(start.begin(), start.end() - 1);
        for(int i = 0; i < m; ++i){
            adj[it[ea[i]]++] = eb[i];
            adj[it[eb[i]]++] = ea[i];
        }
    }
    // BFS para obter ordem (pais antes de filhos) e pais
    vector<int> order(n), par(n, -1);
    {
        int qt = 0;
        order[qt++] = 0;
        for(int qh = 0; qh < qt; ++qh){
            int u = order[qh];
            for(int j = start[u]; j < start[u + 1]; ++j){
                int w = adj[j];
                if(w != par[u]){
                    par[w] = u;
                    order[qt++] = w;
                }
            }
        }
    }
    vector<int> f(n), b(n);
    const int INF = 1000000000;

    // Verifica se K radares de raio R bastam (guloso bottom-up, O(n))
    auto check = [&](int R)->bool{
        for(int i = 0; i < n; ++i){ f[i] = -1; b[i] = INF; }
        long long cnt = 0;
        for(int i = n - 1; i >= 1; --i){
            int v = order[i];
            int fv = f[v], bv = b[v];
            if(bv > R){
                // v nao esta coberto; v em si passa a ser pendente a distancia 0
                if(fv < 0) fv = 0;
            } else if(fv >= 0 && bv + fv <= R){
                // radar mais proximo cobre todos os pendentes (o mais distante esta a fv)
                fv = -1;
            }
            if(fv == R){
                // pendente mais profundo a exatamente R: obrigado a colocar radar em v
                cnt++; fv = -1; bv = 0;
            }
            int p = par[v];
            if(fv >= 0 && fv + 1 > f[p]) f[p] = fv + 1;
            if(bv + 1 < b[p]) b[p] = bv + 1;
        }
        {
            int fv = f[0], bv = b[0];
            if(bv > R){
                if(fv < 0) fv = 0;
            } else if(fv >= 0 && bv + fv <= R){
                fv = -1;
            }
            if(fv >= 0) cnt++; // radar na raiz cobre os pendentes restantes (dist <= fv <= R)
        }
        return cnt <= K;
    };

    int lo = 0, hi = n;
    while(lo < hi){
        int mid = lo + (hi - lo) / 2;
        if(check(mid)) hi = mid; else lo = mid + 1;
    }
    cout << lo << "\n";
    return 0;
}
